example:
capability Orders = D1
capability Sessions = Kv

fn touch(id: String) -> Effect[()] given Orders {
	forget(id, given Store = Orders)     // ✗ `Orders` is a `D1`, and `Store` takes a `Kv`
}

fn touch(id: String) -> Effect[()] given Sessions {
	forget(id, given Store = Sessions)   // ✓ an instance of `Kv`
}
